CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,mobile VARCHAR(11) NOT NULL UNIQUE,name VARCHAR(190) NOT NULL DEFAULT '',active TINYINT NOT NULL DEFAULT 1,session_version INT UNSIGNED NOT NULL DEFAULT 1,verified_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS user_roles(user_id BIGINT UNSIGNED NOT NULL,role ENUM('patient','doctor','secretary','clinic') NOT NULL,PRIMARY KEY(user_id,role),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS doctor_accounts(doctor_id BIGINT UNSIGNED PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,FOREIGN KEY(doctor_id) REFERENCES doctors(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS staff_scopes(user_id BIGINT UNSIGNED NOT NULL,clinic_id BIGINT UNSIGNED NOT NULL,role ENUM('secretary','clinic') NOT NULL,PRIMARY KEY(user_id,clinic_id,role),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(clinic_id) REFERENCES clinics(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS otp_challenges(id CHAR(64) PRIMARY KEY,mobile VARCHAR(11) NOT NULL,code_hash VARCHAR(255) NOT NULL,session_hash CHAR(64) NOT NULL,created_at BIGINT UNSIGNED NOT NULL,expires_at BIGINT UNSIGNED NOT NULL,attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,consumed_at BIGINT UNSIGNED NULL,delivery_status VARCHAR(20) NOT NULL DEFAULT 'pending',provider_id VARCHAR(40) NULL,INDEX otp_mobile(mobile,created_at),INDEX otp_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS auth_rate_limits(bucket VARCHAR(100) PRIMARY KEY,window_start BIGINT UNSIGNED NOT NULL,hits INT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_user_id BIGINT UNSIGNED NULL,actor_admin_id BIGINT UNSIGNED NULL,action VARCHAR(80) NOT NULL,entity_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX audit_time(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
